head.script:
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.gPvd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.getParentValue();
        // fn_getParam();

        // 가우스헤더 셋팅
        // dts_StudyCond.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLSTUDYCOND_IN";
        // dts_StudyCond.reset();

        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30204.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_DsclAcptListAll_OnClick
 * @description grd_DsclAcptListAll 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_DsclAcptListAll_OnClick = async function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "ACPT_DATE") {
            // 부모창에 셋팅하기
            $c.frame.path("../").txb_acptno.setValue(dts_DsclAcptListAll.getCellData(row, "ACPT_NO"));
            $c.frame.path("../").txb_acpt_ddtm.setValue(dts_DsclAcptListAll.getCellData(row, "ACPT_DATE"));
            $c.frame.path("../").txb_doc_title.setValue(dts_DsclAcptListAll.getCellData(row, "DOC_TITLE"));
            // self.close();
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30204.grd_DsclAcptListAll_OnClick" });
    }
};

/**
 * @method
 * @name grd_DsclAcptListAll_OnDblClick
 * @description grd_DsclAcptListAll 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_DsclAcptListAll_OnDblClick = async function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        const result = "";
        if (colid === "DOC_TITLE") {
            /*
            var url = "/dsclproc/ULDSTF10001.gfm";
            var winTitle ="임시제목  - (회사명/보고서명/접수날짜)";
            frame.CreateDialogFrame("gform", url , winTitle ,100, 10, 1000, 800, "window" );
            //frame.CreateFrame("viewer", url , winTitle ,10, 10, 1000, 800, "window" , 0, 0, true);
             */
            await $c.stf.openDisclViewer(scwin.gAcptNo, 'R');
        } else if (colid === "ACPT_DATE") {
            // 부모창에 셋팅하기
            $c.frame.path("../").txb_acptno.setValue(dts_DsclAcptListAll.getCellData(row, "ACPT_NO"));
            $c.frame.path("../").txb_acpt_ddtm.setValue(dts_DsclAcptListAll.getCellData(row, "ACPT_DATE"));
            $c.frame.path("../").txb_doc_title.setValue(dts_DsclAcptListAll.getCellData(row, "DOC_TITLE"));
            // self.close();
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30204.grd_DsclAcptListAll_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_DsclAcptListAll_OnLoadError
 * @description dts_DsclAcptListAll 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclAcptListAll_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_DsclAcptListAll);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30204.dts_DsclAcptListAll_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DsclAcptListAll_OnLoadCompleted
 * @description dts_DsclAcptListAll 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclAcptListAll_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_DsclAcptListAll.errorMsg) {
            await $c.win.alert(dts_DsclAcptListAll.errorMsg);
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30204.dts_DsclAcptListAll_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        // self.close();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30204.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF30204.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_DsclAcptListAll, {fileName: "제출보고서 목록", type: "2"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30204.btn_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 화면 로딩시 디폴트 검색
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const sbmOptions = {
        id : "sbm_dts_DsclAcptListAll",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_DsclAcptListAll=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParentValue
 * @description get Parent Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParentValue = function() {
    // gAcptNo = frame.Provider("../").gAcptNo;
    // gMainFormCd = frame.Provider("../").gMainFormCd;
    // gFormVer = frame.Provider("../").gFormVer;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    // alert("회사코드:"+gIsurCd);

};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclAcptListAll.getCellData(Number(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclAcptListAll.getCellData(Number(obj), "FORM_CD");
    scwin.gFormVer = dts_DsclAcptListAll.getCellData(Number(obj), "FORM_VER");
    scwin.gIsurCd = dts_DsclAcptListAll.getCellData(Number(obj), "ISUR_CD");

    // alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
